using System.ComponentModel.DataAnnotations;

namespace INKED.Application.OrderItems;

/// <summary>
/// Data the client sends to add a product line to an order. OrderItemID and LineTotal are
/// generated by SQL Server, so they are not sent.
/// MP1 Table 10: "Quantity and UnitPrice are copied from the accepted quotation", so if
/// Quantity or UnitPrice is left empty, the value is copied from the matching quotation line.
/// </summary>
public class CreateOrderItemDto
{
    /// <summary>Must be an existing OrderID that is not locked.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "OrderId must be an existing order ID.")]
    public int OrderId { get; set; }

    /// <summary>Must be a product that appears in the order's quotation.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "ProductId must be an existing product ID.")]
    public int ProductId { get; set; }

    /// <summary>Optional. Greater than 0. Empty = copy from the quotation line.</summary>
    [Range(1, int.MaxValue, ErrorMessage = "Quantity must be greater than 0.")]
    public int? Quantity { get; set; }

    /// <summary>Optional. DECIMAL(10,2), 0 or more. Empty = copy from the quotation line.</summary>
    [Range(typeof(decimal), "0", "99999999.99", ErrorMessage = "UnitPrice must be from 0 to 99,999,999.99.")]
    public decimal? UnitPrice { get; set; }

    /// <summary>VARCHAR(500), optional.</summary>
    [StringLength(500)]
    public string? ProductionNotes { get; set; }
}
